exercises.solutionCode:
#include <stddef.h>
typedef struct {
    int locals_bytes;
    int call_depth;
    int regs_per_frame;
    int stack_alloc_bytes;
} TaskStackInfo;

int task_stack_evaluate(const TaskStackInfo *info, int *need_bytes)
{
    if (info == NULL || need_bytes == NULL) {
        return -1;
    }

    if (info->locals_bytes <= 0 || info->call_depth <= 0 ||
        info->regs_per_frame <= 0 || info->stack_alloc_bytes <= 0) {
        return -1;
    }

    int need = info->locals_bytes +
               info->call_depth * info->regs_per_frame * 4;

    *need_bytes = need;

    return (info->stack_alloc_bytes >= need) ? 0 : 1;
}
